interface TripIconProps {
  name: TripIconName;
  size?: number;
  /** Stroke color — defaults to the Figma ink (#222B30). */
  color?: string;
  /** Stroke weight in the icon's own viewBox units. Default 1.5; lower = thinner. */
  strokeWidth?: number;
}

export const TripIcon: React.FC<TripIconProps> = ({
  name,
  size = 18,
  color = '#222B30',
  strokeWidth = 1,
}) => {
  const icon = ICONS[name];
  // Filled glyphs (e.g. edit-03) paint the path with `fill`; the rest are
  // stroked outlines recolored via `stroke`.
  if (icon.filled) {
    return (
      <Svg width={size} height={size} viewBox={icon.viewBox} fill="none">
        <Path d={icon.d} fill={color} fillRule={icon.evenOdd ? 'evenodd' : 'nonzero'} />
      </Svg>
    );
  }
  return (
    <Svg width={size} height={size} viewBox={icon.viewBox} fill="none">
      <Path
        d={icon.d}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </Svg>
  );
};

export default TripIcon;

// DragHandleIcon — the Figma "dots-vertical" drag grip (node 12919:32671): three
// stacked dots, each filled #212121 with a #333 hairline. Used as the reorder
// handle on gear rows. (Filled + stroked, so it can't ride the TripIcon path set.)
export const DragHandleIcon: React.FC<{ size?: number; strokeWidth?: number }> = ({
  size = 22,
  strokeWidth = 1,
}) => (
  <Svg width={size} height={size} viewBox="0 0 22 22" fill="none">
    {[4.5834, 11.0001, 17.4167].map(cy => (
      <Circle
        key={cy}
        cx={10.9987}
        cy={cy}
        r={0.9167}
        fill="#212121"
        stroke="#333333"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    ))}
  </Svg>
);
